<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { releaseNotes } from '../config/releaseNotes';
import { publicDownloadUrl } from '../utils/publicDownload';
interface Release {version:string;size:number;sha256:string;filename:string}
const release=ref<Release|null>(null),access=ref('loading'),loading=ref(false),copied=ref(false),copyFailed=ref(false),downloadStarted=ref(false);
let controller:AbortController|undefined;let alive=true;
const publicUrl=computed(()=>publicDownloadUrl(release.value));
const statusText=computed(()=>({loading:'正在检查下载权限…','login-required':'登录你的墨屿账号，即可获取试用安装包。',allowed:'账号验证通过，可以下载。',restricted:'当前账号暂不能下载。请确认账号未被封禁，并已完成必要的密码修改。',unavailable:'暂时无法验证下载权限，请稍后重试。'}[access.value]||'暂时无法验证下载权限。'));
async function refresh(){controller?.abort();const current=new AbortController();controller=current;loading.value=true;const timer=setTimeout(()=>current.abort(),8000);try{const r=await fetch('/api/download/status',{credentials:'same-origin',cache:'no-store',signal:current.signal});const body=await r.json();if(!alive||controller!==current)return;const item=body.release;if(item&&typeof item.version==='string'&&typeof item.size==='number'&&/^[a-f0-9]{64}$/.test(item.sha256))release.value=item;access.value=['login-required','allowed','restricted'].includes(body.access)&&r.ok?body.access:'unavailable';}catch{if(alive&&controller===current)access.value='unavailable';}finally{clearTimeout(timer);if(alive&&controller===current)loading.value=false;}}
async function copyHash(){copyFailed.value=false;try{await navigator.clipboard.writeText(release.value?.sha256||'');copied.value=true;}catch{copyFailed.value=true;}}
function resumed(){if(document.visibilityState==='visible')void refresh();}
onMounted(()=>{void refresh();window.addEventListener('focus',resumed);document.addEventListener('visibilitychange',resumed);});onBeforeUnmount(()=>{alive=false;controller?.abort();window.removeEventListener('focus',resumed);document.removeEventListener('visibilitychange',resumed);});
</script>
